from fractions import Fraction

def gaussian_elimination(A):
    n = len(A)
    for i in range(n):
        # Find pivot
        max_row = i
        for k in range(i+1, n):
            if abs(A[k][i]) > abs(A[max_row][i]):
                max_row = k
        A[i], A[max_row] = A[max_row], A[i]

        # Eliminate below
        factor = Fraction(A[i][i])
        for k in range(i+1, n):
            A[k][i] /= factor

        # Eliminate above
        for k in range(i):
            factor = Fraction(A[k][i])
            for j in range(n):
                A[k][j] -= factor * A[i][j]
    return A

def coxeter_matrix_invariant(G):
    n = len(G)
    M = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i, n):
            if G[i][j] != 0:
                M[i][j] = G[i][j]
                M[j][i] = G[i][j]

    # Ensure the matrix is symmetric
    for i in range(n):
        for j in range(i+1, n):
            M[j][i] = M[i][j]

    # Perform Gaussian elimination to get the invariant
    M = gaussian_elimination(M)

    # Calculate the determinant (invariant)
    det = 1
    for i in range(n):
        det *= M[i][i]

    return abs(det)

def read_twice_bp_instance(n):
    # Generate a random read-twice branching program instance
    bp = []
    for _ in range(n):
        bp.append(random.choice([0, 1]))
    return bp

def compute_coxeter_group(bp):
    n = len(bp)
    G = [[0] * n for _ in range(n)]

    # Compute the Coxeter group matrix
    for i in range(n):
        for j in range(i+1, n):
            if bp[i] != bp[j]:
                G[i][j] = 2
                G[j][i] = 2

    return G

def run_trial(seed: int) -> dict:
    random.seed(seed)

    metric_name = "Coxeter Matrix Invariant vs BP_ReadTwice Circuit Size"
    instances_tested = 0
    total_rho_G = 0.0
